import signal
import sys
import time
from gpiozero import OutputDevice
from gpiozero.exc import GPIODeviceError, GPIOPinInUse

PINS = [2, 3, 4]
DELAY = 60

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    devices = []
    try:
        for pin in PINS:
            try:
                dev = OutputDevice(pin)
                devices.append(dev)
                print(f"GPIO {pin} configured as output (initial state: off)")
            except (GPIODeviceError, GPIOPinInUse) as e:
                print(f"Error: failed to configure GPIO {pin}: {e}", file=sys.stderr)
                for d in devices:
                    d.close()
                sys.exit(1)
            except Exception as e:
                print(f"Unexpected error configuring GPIO {pin}: {e}", file=sys.stderr)
                for d in devices:
                    d.close()
                sys.exit(1)

        while _running:
            for dev in devices:
                try:
                    dev.on()
                    print(f"GPIO {dev.pin.number} set to HIGH")
                except Exception as e:
                    print(f"Error setting GPIO {dev.pin.number} HIGH: {e}", file=sys.stderr)
                    for d in devices:
                        d.close()
                    sys.exit(1)
            time.sleep(DELAY)

            for dev in devices:
                try:
                    dev.off()
                    print(f"GPIO {dev.pin.number} set to LOW")
                except Exception as e:
                    print(f"Error setting GPIO {dev.pin.number} LOW: {e}", file=sys.stderr)
                    for d in devices:
                        d.close()
                    sys.exit(1)
            time.sleep(DELAY)

    finally:
        for dev in devices:
            try:
                dev.close()
            except Exception:
                pass
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

import signal
import sys
import time
from gpiozero import PWMOutputDevice

PWM_PINS = [1, 2, 3, 4]
DELAY = 0.1

running = True
devices = []

def handle_signal(signum, frame):
    global running
    running = False

def cleanup():
    for dev in devices:
        try:
            dev.close()
        except Exception:
            pass
    devices.clear()

def apply_pwm_values(values):
    if len(values) != len(PWM_PINS):
        raise ValueError("Number of values must match number of pins")
    for i, val in enumerate(values):
        if not (0.0 <= val <= 1.0):
            raise ValueError(f"Value at index {i} out of range: {val}")
        devices[i].value = val
    print(f"PWM values set: {values}")

def main():
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        for pin in PWM_PINS:
            dev = PWMOutputDevice(pin)
            dev.value = 0.0
            devices.append(dev)
    except Exception as e:
        print(f"Failed to initialize PWM devices: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    try:
        while running:
            try:
                user_input = input("Enter PWM values (comma-separated, 0.0-1.0): ")
                values = [float(v.strip()) for v in user_input.split(",")]
                apply_pwm_values(values)
            except ValueError as e:
                print(f"Invalid input: {e}", file=sys.stderr)
            except EOFError:
                break
            time.sleep(DELAY)
    finally:
        cleanup()

if __name__ == "__main__":
    main()

