            time.sleep(LOOP_INTERVAL)

    except serial.SerialException as e:
        print(f"Failed to open serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)
    except OSError as e:
        print(f"OS error opening serial port: {e}", file=sys.stderr)
        sys.exit(1)
