import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 115200
READ_TIMEOUT = 2.0
POLL_INTERVAL = 5.0

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def _validate_reading(value):
    if not isinstance(value, (int, float)):
        return False
    if value < -20.0 or value > 125.0:
        return False
    return True

def _read_sensor(ser):
    try:
        line = ser.readline()
    except serial.SerialException as exc:
        print(f"Serial read error: {exc}", file=sys.stderr)
        return None
    if not line:
        return None
    try:
        raw = line.decode('ascii', errors='replace').strip()
    except Exception as exc:
        print(f"Decode error: {exc}", file=sys.stderr)
        return None
    if not raw:
        return None
    try:
        value = float(raw)
    except ValueError:
        print(f"Invalid data format: {raw!r}", file=sys.stderr)
        return None
    if not _validate_reading(value):
        print(f"Out-of-range reading: {value}", file=sys.stderr)
        return None
    return value

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            timeout=READ_TIMEOUT,
        )
    except serial.SerialException as exc:
        print(f"Failed to open {SERIAL_PORT}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            reading = _read_sensor(ser)
            if reading is not None:
                print(f"Sensor reading: {reading}")
            else:
                print("No valid reading received this cycle.")
            time.sleep(POLL_INTERVAL)
    finally:
        try:
            ser.close()
        except Exception:
            pass
        print("Serial port closed. Exiting.")

if __name__ == '__main__':
    main()

import serial
import signal
import sys
import time

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 115200
TIMEOUT_S = 2.0
MAX_RETRIES = 3
RETRY_DELAY_S = 0.5

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def _is_valid_reading(line: str) -> bool:
    """Return True if the line is a well-formed sensor reading."""
    if not line:
        return False
    parts = line.split(',')
    if len(parts) != 3:
        return False
    try:
        temp = float(parts[0])
        hum = float(parts[1])
        ts = int(parts[2])
    except ValueError:
        return False
    if not (-40.0 <= temp <= 85.0) or not (0.0 <= hum <= 100.0):
        return False
    return True

def _read_once(ser: serial.Serial) -> str | None:
    """Read one line from the serial port; return None on timeout/error."""
    try:
        raw = ser.readline()
    except serial.SerialException as exc:
        print(f"Serial read error: {exc}", file=sys.stderr)
        return None
    if not raw:
        return None
    return raw.decode('ascii', errors='replace').strip()

def main() -> int:
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    ser = None
    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=TIMEOUT_S,
        )
    except serial.SerialException as exc:
        print(f"Failed to open {SERIAL_PORT}: {exc}", file=sys.stderr)
        return 1

    try:
        for attempt in range(1, MAX_RETRIES + 1):
            if not _running:
                print("Interrupted by signal.", file=sys.stderr)
                return 130

            line = _read_once(ser)
            if line is None:
                print(f"Attempt {attempt}/{MAX_RETRIES}: no response from device.", file=sys.stderr)
                if attempt < MAX_RETRIES:
                    time.sleep(RETRY_DELAY_S)
                continue

            if not _is_valid_reading(line):
                print(f"Attempt {attempt}/{MAX_RETRIES}: invalid reading '{line}'", file=sys.stderr)
                if attempt < MAX_RETRIES:
                    time.sleep(RETRY_DELAY_S)
                continue

            print(f"Valid reading: {line}")
            return 0

        print("Max retries reached; no valid reading obtained.", file=sys.stderr)
        return 1
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == '__main__':
    sys.exit(main())

import signal
import sys
import time

from gpiozero import DistanceSensor
from gpiozero.exc import GPIOZeroError, DeviceClosed

# HC-SR04 wiring (BCM numbering)
TRIGGER_PIN = 17
ECHO_PIN = 22
SAMPLE_INTERVAL = 50  # seconds between measurements
NUM_SAMPLES = 5
MAX_MEASURE_TIME = 1.0  # seconds – gpiozero raises on timeout

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def measure_distance(trigger_pin, echo_pin):
    """Return distance in cm, or None on timeout / error."""
    try:
        sensor = DistanceSensor(
            echo=echo_pin,
            trigger=trigger_pin,
            max_distance=4.0,
            threshold_distance=0.02,
        )
    except GPIOZeroError as exc:
        print(f"Error: failed to initialise sensor: {exc}", file=sys.stderr)
        return None

    try:
        distance = sensor.distance * 100.0  # metres -> cm
        if distance < 2.0 or distance > 400.0:
            print("Warning: reading out of valid range (2–400 cm).", file=sys.stderr)
            return None
        return distance
    except DeviceClosed:
        print("Error: device was closed before reading.", file=sys.stderr)
        return None
    except GPIOZeroError as exc:
        print(f"Error: measurement failed: {exc}", file=sys.stderr)
        return None
    finally:
        try:
            sensor.close()
        except Exception:
            pass


def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    samples_taken = 0
    while _running and samples_taken < NUM_SAMPLES:
        distance = measure_distance(TRIGGER_PIN, ECHO_PIN)
        if distance is not None:
            print(f"Distance: {distance:.2f} cm")
        else:
            print("Distance: unavailable")
        samples_taken += 1
        if _running and samples_taken < NUM_SAMPLES:
            time.sleep(SAMPLE_INTERVAL)

    print("Program finished.")


if __name__ == "__main__":
    main()

