import signal
import sys
import time
from gpiozero import OutputDevice
from gpiozero.exc import GPIODeviceError, GPIOPinInUse

PIN = 17
DELAY = 60
MAX_ATTEMPTS = 3
RETRY_DELAY = 2

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def set_output(device, state):
    if state:
        device.on()
    else:
        device.off()
    print(f"GPIO {device.pin.number} set to {state}")

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        device = OutputDevice(PIN)
    except (GPIODeviceError, GPIOPinInUse) as e:
        print(f"Error: cannot initialize GPIO {PIN}: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error initializing GPIO {PIN}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            for state in (True, False):
                if not _running:
                    break
                try:
                    set_output(device, state)
                except Exception as e:
                    print(f"Error writing to GPIO {PIN}: {e}", file=sys.stderr)
                    break
                time.sleep(DELAY)
    finally:
        try:
            device.close()
        except Exception:
            pass

if __name__ == "__main__":
    main()

