import time
import signal
import sys
from RPLCD.i2c import CharLCD

LCD_I2C_ADDR = 0x27
LCD_COLS = 16
LCD_ROWS = 2
UPDATE_INTERVAL = 0.005

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def get_sensor_reading():
    """Return a valid sensor reading, or None if invalid."""
    return 42.0

def display_sensor_data(lcd, sensor_value):
    """Write the sensor value to the LCD."""
    lcd.clear()
    lcd.write_string(f"Sensor: {sensor_value:.2f}")

def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        lcd = CharLCD('PCF8574', LCD_I2C_ADDR, cols=LCD_COLS, rows=LCD_ROWS)
    except Exception as exc:
        print(f"Failed to initialize LCD at 0x{LCD_I2C_ADDR:02X}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            sensor_value = get_sensor_reading()
            if sensor_value is None:
                print("Invalid sensor reading, skipping update.", file=sys.stderr)
            else:
                display_sensor_data(lcd, sensor_value)
            time.sleep(UPDATE_INTERVAL)
    except Exception as exc:
        print(f"Runtime error: {exc}", file=sys.stderr)
    finally:
        try:
            lcd.clear()
            lcd.close()
        except Exception:
            pass

if __name__ == "__main__":
    main()

