import signal
import sys
import time

import board
import busio
import adafruit_ads1x15.ads1015 as ADS
from adafruit_ads1x15.analog_in import AnalogIn

# --- Configuration -----------------------------------------------------------
I2C_ADDRESS = 0x48          # ADS1015 default I2C address (ADDR -> GND)
SAMPLE_INTERVAL_S = 1.0     # Delay between readings
# -----------------------------------------------------------------------------

_running = True


def _handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


def main() -> int:
    global _running

    # Install signal handlers for clean exit
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    # Initialize I2C bus (board.SCL / board.SDA uses the Pi's hardware I2C pins)
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        print(f"Error: failed to initialize I2C bus: {exc}", file=sys.stderr)
        return 1

    # Initialize the ADS1015 at the specified address
    try:
        ads = ADS.ADS1015(i2c, address=I2C_ADDRESS)
    except ValueError:
        print(f"Error: no ADS1015 found at I2C address 0x{I2C_ADDRESS:02X}.", file=sys.stderr)
        return 1
    except Exception as exc:
        print(f"Error: failed to initialize ADS1015: {exc}", file=sys.stderr)
        return 1

    # Create a single-ended analog input on channel 0
    try:
        chan = AnalogIn(ads, ADS.P0)
    except Exception as exc:
        print(f"Error: failed to configure analog input: {exc}", file=sys.stderr)
        return 1

    print("Starting ADS1015 sampling. Press Ctrl+C to stop.")

    try:
        while _running:
            try:
                voltage = chan.voltage
                # Basic sanity check: ADS1015 is 12-bit, so voltage should be in [0, 3.3]
                if not (0.0 <= voltage <= 3.3):
                    print(f"Warning: out-of-range reading {voltage:.4f} V", file=sys.stderr)
                else:
                    print(f"Reading: {voltage:.4f} V")
            except OSError as exc:
                # I2C bus error (e.g., device disconnected mid-stream)
                print(f"Error: I2C bus error: {exc}", file=sys.stderr)
            except Exception as exc:
                print(f"Error: unexpected reading failure: {exc}", file=sys.stderr)

            # Sleep in small increments so signals are caught promptly
            slept = 0.0
            while _running and slept < SAMPLE_INTERVAL_S:
                time.sleep(0.1)
                slept += 0.1

    finally:
        # Release hardware resources on every exit path
        try:
            chan.deinit()
        except Exception:
            pass
        try:
            ads.deinit()
        except Exception:
            pass
        try:
            i2c.deinit()
        except Exception:
            pass
        print("Resources released. Exiting.")

    return 0


if __name__ == "__main__":
    sys.exit(main())

