import signal
import sys
import time
from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError

PINS = [4, 17, 22, 27]
DELAY = 1.0
MAX_RETRIES = 3
RETRY_DELAY = 0.5

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_sensor():
    """Simulate a sensor reading. Returns a float in [0.0, 1.0] or None on failure."""
    import random
    if random.random() < 0.1:
        return None
    return random.random()

def apply_state(pwm_devices, value):
    """Apply a validated sensor value to all PWM devices."""
    for dev in pwm_devices:
        dev.value = value
    print(f"PWM values set to: {value:.4f}")

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        pwm_devices = [PWMOutputDevice(pin) for pin in PINS]
    except GPIOZeroError as exc:
        print(f"Failed to initialize PWM devices: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            reading = None
            for attempt in range(1, MAX_RETRIES + 1):
                reading = read_sensor()
                if reading is not None:
                    break
                if attempt < MAX_RETRIES:
                    time.sleep(RETRY_DELAY)

            if reading is None:
                print("Sensor read failed after retries; exiting.", file=sys.stderr)
                break

            if not (0.0 <= reading <= 1.0):
                print(f"Invalid sensor value {reading}; exiting.", file=sys.stderr)
                break

            apply_state(pwm_devices, reading)

            time.sleep(DELAY)
    finally:
        for dev in pwm_devices:
            try:
                dev.close()
            except Exception:
                pass
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 115200
READ_TIMEOUT = 2.0
LOOP_INTERVAL = 1.0

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def _is_valid_reading(data: str) -> bool:
    """Return True if the received string is a plausible sensor reading."""
    if not data:
        return False
    try:
        value = float(data)
    except ValueError:
        return False
    return -100.0 <= value <= 100.0

def main() -> int:
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            timeout=READ_TIMEOUT,
        )
    except serial.SerialException as exc:
        print(f"Error: cannot open {SERIAL_PORT}: {exc}", file=sys.stderr)
        return 1

    try:
        while _running:
            try:
                raw = ser.readline()
            except serial.SerialException as exc:
                print(f"Error: serial read failed: {exc}", file=sys.stderr)
                break

            if not raw:
                print("Error: no data received (device unresponsive or cable issue)")
                break

            data = raw.decode('ascii', errors='replace').strip()
            if not _is_valid_reading(data):
                print(f"Error: invalid reading '{data}'")
                break

            print(f"Sensor Reading: {data}")

            time.sleep(LOOP_INTERVAL)
    finally:
        try:
            ser.close()
        except Exception:
            pass

    return 0

if __name__ == '__main__':
    sys.exit(main())

