import time
import signal
import sys

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 9600
TIMEOUT_S = 1.0
READ_INTERVAL_S = 1.0
MAX_RETRIES = 3

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def _open_serial():
    try:
        return serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=TIMEOUT_S,
        )
    except serial.SerialException as exc:
        print(f"Error: cannot open {SERIAL_PORT}: {exc}", file=sys.stderr)
        sys.exit(1)

def _read_once(ser):
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            raw = ser.readline()
        except serial.SerialException as exc:
            print(f"Error: serial read failed (attempt {attempt}/{MAX_RETRIES}): {exc}", file=sys.stderr)
            return None
        if not raw:
            print(f"Warning: no data received (attempt {attempt}/{MAX_RETRIES})", file=sys.stderr)
            continue
        line = raw.decode('ascii', errors='replace').strip()
        if not line:
            print("Warning: empty line received", file=sys.stderr)
            continue
        try:
            value = float(line)
        except ValueError:
            print(f"Warning: non-numeric data received: {line!r}", file=sys.stderr)
            continue
        if not (-100.0 <= value <= 100.0):
            print(f"Warning: value {value} out of range [-100, 100]", file=sys.stderr)
            continue
        return value
    print("Error: device unresponsive after retries", file=sys.stderr)
    return None

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    ser = _open_serial()
    print(f"Serial port {SERIAL_PORT} opened at {BAUD_RATE} baud.")

    try:
        while _running:
            reading = _read_once(ser)
            if reading is not None:
                print(f"Sensor reading: {reading:.2f}")
            time.sleep(READ_INTERVAL_S)
    finally:
        try:
            ser.close()
        except Exception:
            pass
        print("Serial port closed. Exiting.")

if __name__ == '__main__':
