import serial
import signal
import sys
import time

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 115200
TIMEOUT_S = 2.0
MAX_RETRIES = 3
RETRY_DELAY_S = 0.5

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def _open_serial():
    try:
        return serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=TIMEOUT_S,
        )
    except serial.SerialException as exc:
        print(f"Error: cannot open {SERIAL_PORT}: {exc}", file=sys.stderr)
        return None
    except OSError as exc:
        print(f"Error: device not available {SERIAL_PORT}: {exc}", file=sys.stderr)
        return None

def _read_once(ser):
    try:
        raw = ser.readline()
    except serial.SerialException as exc:
        print(f"Error: serial read failed: {exc}", file=sys.stderr)
        return None
    if not raw:
        return None
    try:
        text = raw.decode('ascii', errors='replace').strip()
    except Exception as exc:
        print(f"Error: decode failed: {exc}", file=sys.stderr)
        return None
    if not text:
        return None
    try:
        value = float(text)
    except ValueError:
        print(f"Error: non-numeric data '{text}'", file=sys.stderr)
        return None
    if not (-100.0 <= value <= 100.0):
        print(f"Error: value {value} out of range [-100, 100]", file=sys.stderr)
        return None
    return value

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    ser = _open_serial()
    if ser is None:
        sys.exit(1)

    try:
        for attempt in range(1, MAX_RETRIES + 1):
            if not _running:
                print("Aborted by signal.", file=sys.stderr)
                sys.exit(130)
            value = _read_once(ser)
            if value is not None:
                print(f"Temperature: {value:.2f} C")
                sys.exit(0)
            if attempt < MAX_RETRIES:
                time.sleep(RETRY_DELAY_S)
        print("Error: no valid reading within retries.", file=sys.stderr)
        sys.exit(1)
    finally:
        try:
            ser.close()
        except Exception:
            pass

if __name__ == '__main__':
    main()

import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

I2C_BUS = 1
TSL2561_ADDR = 0x39
REG_COMMAND = 0x80
REG_CONTROL = 0x80
REG_DATA0_LOW = 0x8C
REG_DATA1_LOW = 0x8E

CMD_POWER_ON = 0x03
CMD_POWER_OFF = 0x00
CMD_CLEAR_INTERRUPT = 0x40

running = True


def _signal_handler(signum, frame):
    global running
    running = False


def _write_reg(bus, reg, value):
    msg = i2c_msg.write(TSL2561_ADDR, [reg, value])
    bus.i2c_rdwr(msg)


def _read_reg(bus, reg):
    write_msg = i2c_msg.write(TSL2561_ADDR, [reg])
    read_msg = i2c_msg.read(TSL2561_ADDR, 2)
    bus.i2c_rdwr(write_msg, read_msg)
    data = list(read_msg)
    return (data[0] << 8) | data[1]


def _read_channel(bus, reg):
    return _read_reg(bus, reg)


def _init_sensor(bus):
    _write_reg(bus, REG_COMMAND | REG_CONTROL, CMD_POWER_ON)
    time.sleep(0.01)
    _write_reg(bus, REG_COMMAND | REG_CONTROL, CMD_CLEAR_INTERRUPT)


def _read_lux(bus):
    ch0 = _read_channel(bus, REG_DATA0_LOW)
    ch1 = _read_channel(bus, REG_DATA1_LOW)
    if ch0 == 0xFFFF or ch1 == 0xFFFF:
        return None
    if ch0 == 0 or ch1 == 0:
        return 0.0
    ratio = ch1 / ch0
    if ratio <= 0.52:
        lux = 0.0315 * ch0 - 0.05934 * ch0 * (ratio ** 1.4)
    elif ratio <= 0.65:
        lux = 0.02291 * ch0 - 0.02916 * ch1
    elif ratio <= 0.80:
        lux = 0.01579 * ch0 - 0.01801 * ch1
    elif ratio <= 1.3:
        lux = 0.00338 * ch0 - 0.00260 * ch1
    else:
        lux = 0.0
    return max(0.0, lux)


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        bus = SMBus(I2C_BUS)
    except OSError as e:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        _init_sensor(bus)
    except OSError as e:
        print(f"Error: TSL2561 not detected at 0x{TSL2561_ADDR:02X}: {e}", file=sys.stderr)
        bus.close()
        sys.exit(1)

    try:
        while running:
            lux = _read_lux(bus)
            if lux is None:
                print("Error: invalid sensor reading (0xFFFF)", file=sys.stderr)
            else:
                print(f"Light Level: {lux:.2f} lux")
            time.sleep(0.1)
    finally:
        try:
            _write_reg(bus, REG_COMMAND | REG_CONTROL, CMD_POWER_OFF)
        except OSError:
            pass
        bus.close()


if __name__ == "__main__":
    main()

