import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

QMC5883L_ADDR = 0x0D
REG_DATA_X_LSB = 0x00
REG_STATUS = 0x06
REG_CONFIG = 0x09

running = True


def _handle_signal(signum, frame):
    global running
    running = False


def read_word(bus, addr, reg):
    """Read a 16-bit little-endian value from two consecutive registers."""
    write_msg = i2c_msg.write(addr, [reg])
    read_msg = i2c_msg.read(addr, 2)
    bus.i2c_rdwr(write_msg, read_msg)
    data = list(read_msg)
    if len(data) < 2:
        raise IOError("Short read from QMC5883L")
    return data[0] | (data[1] << 8)


def main():
    global running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        bus = SMBus(1)
    except OSError as e:
        print(f"Error: cannot open I2C bus 1: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        # Probe the device with a zero-length write.
        bus.i2c_rdwr(i2c_msg.write(QMC5883L_ADDR, []))
    except OSError as e:
        print(f"Error: no QMC5883L found at 0x{QMC5883L_ADDR:02X}: {e}", file=sys.stderr)
        bus.close()
        sys.exit(1)

    try:
        # Configure: ODR=100Hz, Range=±2G, Continuous mode.
        bus.write_byte_data(QMC5883L_ADDR, REG_CONFIG, 0x01)
        time.sleep(0.01)

        for i in range(3):
            if not running:
                break

            try:
                status = read_word(bus, QMC5883L_ADDR, REG_STATUS)
                if status & 0x01:
                    print(f"Reading {i + 1}/3: data ready, X={read_word(bus, QMC5883L_ADDR, REG_DATA_X_LSB):+6d}")
                else:
                    print(f"Reading {i + 1}/3: data not ready (status=0x{status:02X})")
            except OSError as e:
                print(f"Reading {i + 1}/3: I2C error: {e}", file=sys.stderr)

            if i < 2 and running:
                time.sleep(0.1)
    finally:
        bus.close()


if __name__ == "__main__":
    main()

import time
import signal
import sys
import logging
from picamera2 import Picamera2

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger("camera_capture")

_running = True

def _handle_signal(signum, frame):
    global _running
    log.info("Received signal %s, shutting down...", signum)
    _running = False

def capture_image(camera: Picamera2, filename: str) -> bool:
    """Capture a single image and save it to *filename*. Returns True on success."""
    try:
        camera.capture_file(filename)
        log.info("Image saved to %s", filename)
        return True
    except Exception as exc:
        log.error("Error capturing image: %s", exc)
        return False

def main() -> int:
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        camera = Picamera2()
    except Exception as exc:
        log.error("Failed to initialize camera: %s", exc)
        return 1

    try:
        try:
            camera.start()
        except Exception as exc:
            log.error("Failed to start camera: %s", exc)
            return 1

        while _running:
            if not capture_image(camera, "image.jpg"):
                break
            time.sleep(0.1)
    finally:
        try:
            camera.stop()
        except Exception:
            pass
        try:
            camera.close()
        except Exception:
            pass
        log.info("Camera resources released.")

    return 0

if __name__ == "__main__":
    sys.exit(main())

