import signal
import sys
import time

from gpiozero import AngularServo
from gpiozero.pins.native import NativeFactory

# SG90 pulse-width range: 0.5 ms (0°) to 2.5 ms (180°)
MIN_PULSE = 0.5 / 1000
MAX_PULSE = 2.5 / 1000

# BCM GPIO 4 and 18
PINS = [4, 18]
INTERVAL = 5.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    # NativeFactory avoids the need for pigpio daemon while still supporting
    # hardware PWM on GPIO 4 and 18.
    try:
        factory = NativeFactory()
    except Exception as exc:
        print(f"Failed to initialize GPIO factory: {exc}", file=sys.stderr)
        sys.exit(1)

    servos = []
    try:
        for pin in PINS:
            try:
                servo = AngularServo(
                    pin,
                    initial_angle=0,
                    min_angle=0,
                    max_angle=180,
                    min_pulse_width=MIN_PULSE,
                    max_pulse_width=MAX_PULSE,
                    pin_factory=factory,
                )
                servos.append(servo)
            except Exception as exc:
                print(f"Failed to initialize servo on GPIO {pin}: {exc}", file=sys.stderr)
                raise

        while _running:
            for angle in (0, 180):
                if not _running:
                    break
                for servo in servos:
                    try:
                        servo.angle = angle
                        print(f"GPIO {servo.pin.number} -> {angle}°")
                    except Exception as exc:
                        print(f"Error setting angle on GPIO {servo.pin.number}: {exc}", file=sys.stderr)
                time.sleep(INTERVAL)

    finally:
        for servo in servos:
            try:
                servo.close()
            except Exception:
                pass
        try:
            factory.close()
        except Exception:
            pass
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

