import time

try:
    from w1thermsensor import W1ThermSensor, SensorNotReadyError, NoSensorFoundError
except ImportError:
    print("ERROR: w1thermsensor is not installed. Install with: pip install w1thermsensor", file=sys.stderr)
    sys.exit(1)

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_temperature():
    """Read temperature from DS18B20. Returns float or None on error."""
    try:
        sensor = W1ThermSensor()
    except NoSensorFoundError:
        print("ERROR: No DS18B20 sensor found on the 1-Wire bus.", file=sys.stderr)
        return None
    except Exception as e:
        print(f"ERROR: Failed to initialize DS18B20 sensor: {e}", file=sys.stderr)
        return None

    try:
        temperature = sensor.get_temperature()
    except SensorNotReadyError:
        print("ERROR: Sensor not ready (conversion in progress).", file=sys.stderr)
        return None
    except Exception as e:
        print(f"ERROR: Failed to read temperature: {e}", file=sys.stderr)
        return None

    if temperature is None:
        print("ERROR: Sensor returned None.", file=sys.stderr)
        return None

    if not -55.0 <= temperature <= 125.0:
        print(f"ERROR: Temperature reading {temperature:.2f}°C out of valid range [-55, 125].", file=sys.stderr)
        return None

    return temperature

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    temperature = read_temperature()
    if temperature is not None:
        print(f"Temperature: {temperature:.2f} °C")
