import signal
import sys
import time
import board
import adafruit_dht

# DHT22 data pins on the Raspberry Pi (BCM numbering)
DATA_PINS = [board.D4, board.D7, board.D11, board.D17]

# Global list so the signal handler can close every device
_devices = []
_running = True


def _cleanup():
    """Release every DHT22 device we opened."""
    for dev in _devices:
        try:
            dev.exit()
        except Exception:
            pass
    _devices.clear()


def _handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


def read_dht22(dev):
    """
    Attempt a temperature/humidity reading.
    Returns (temperature, humidity) or (None, None) on failure.
    """
    try:
        temp = dev.temperature
        hum = dev.humidity
        if temp is None or hum is None:
            return None, None
        # Sanity-check ranges for the DHT22
        if not (-40.0 <= temp <= 80.0):
            return None, None
        if not (0.0 <= hum <= 100.0):
            return None, None
        return temp, hum
    except RuntimeError:
        # Common when the device is not responding or the timing is off
        return None, None
    except Exception:
        return None, None


def main():
    global _devices

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    # Initialize every DHT22 on the specified pins
    for pin in DATA_PINS:
        try:
            dev = adafruit_dht.DHT22(pin, use_pulseio=False)
            _devices.append(dev)
        except Exception as e:
            print(f"Error initializing DHT22 on {pin}: {e}", file=sys.stderr)
            _cleanup()
            sys.exit(1)

    print("DHT22 monitoring started. Press Ctrl+C to stop.")

    try:
        while _running:
            for i, dev in enumerate(_devices):
                temp, hum = read_dht22(dev)
                if temp is not None and hum is not None:
                    print(f"Sensor {i+1} (GPIO {DATA_PINS[i].name}): "
                          f"Temperature = {temp:.1f} C, Humidity = {hum:.1f} %")
                else:
                    print(f"Sensor {i+1} (GPIO {DATA_PINS[i].name}): "
                          f"Failed to read data (device absent or bus error)")
            time.sleep(5)
    finally:
        _cleanup()
        print("Program terminated.")


if __name__ == "__main__":
    main()

