                dev.toggle()
                print(f"GPIO{dev.pin.number} -> {'HIGH' if dev.value else 'LOW'}")
            time.sleep(DELAY)
    except Exception as exc:
        print(f"Runtime error: {exc}", file=sys.stderr)
