import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIODeviceError, GPIOPinInUse

PIN_HIGH = 17
PIN_LOW = 27
DELAY = 0.2

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        dev_high = OutputDevice(PIN_HIGH)
        dev_low = OutputDevice(PIN_LOW)
    except (GPIODeviceError, GPIOPinInUse) as exc:
        print(f"Error: failed to initialize GPIO pins {PIN_HIGH}/{PIN_LOW}: {exc}", file=sys.stderr)
        sys.exit(1)
    except Exception as exc:
        print(f"Error: unexpected failure during GPIO init: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                dev_high.on()
                dev_low.off()
                print(f"GPIO {PIN_HIGH}=HIGH  GPIO {PIN_LOW}=LOW")
            except Exception as exc:
                print(f"Error: failed to set GPIO state: {exc}", file=sys.stderr)
                break

            time.sleep(DELAY)

            if not _running:
                break

            try:
                dev_high.off()
                dev_low.on()
                print(f"GPIO {PIN_HIGH}=LOW   GPIO {PIN_LOW}=HIGH")
            except Exception as exc:
                print(f"Error: failed to set GPIO state: {exc}", file=sys.stderr)
                break

            time.sleep(DELAY)
    finally:
        try:
            dev_high.close()
        except Exception:
            pass
        try:
            dev_low.close()
        except Exception:
            pass
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

import time
import signal
import sys
from RPLCD.i2c import CharLCD

# Global handle so the signal handler can release the display
lcd = None

def cleanup(signum=None, frame=None):
    """Release the LCD and exit cleanly on any signal or normal exit."""
    global lcd
    if lcd is not None:
        try:
            lcd.clear()
            lcd.close()
        except Exception:
            pass
        lcd = None
    if signum is not None:
        sys.exit(0)

def main():
    global lcd

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    # Initialize the I2C LCD (common address 0x27 for most PCF8574 backpacks)
    try:
        lcd = CharLCD('PCF8574', 0x27, cols=16, rows=2)
    except Exception as e:
        print(f"Failed to initialize LCD: {e}", file=sys.stderr)
        sys.exit(1)

    # Display a static message once at startup
    try:
        lcd.clear()
        lcd.write_string("Raspberry Pi\nLCD Demo")
    except Exception as e:
        print(f"Failed to write to LCD: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    # Main loop: update the display every 5 seconds
    while True:
        try:
            lcd.clear()
            lcd.write_string("Temperature: 25C\nHumidity: 60%")
        except Exception as e:
            print(f"Display update failed: {e}", file=sys.stderr)
            # Attempt to recover: close and reopen the bus
            try:
                lcd.close()
            except Exception:
                pass
            try:
                lcd = CharLCD('PCF8574', 0x27, cols=16, rows=2)
            except Exception as init_err:
                print(f"Re-initialization failed: {init_err}", file=sys.stderr)
                cleanup()
                sys.exit(1)

        time.sleep(5)

