import signal
import sys
import time
import board
import adafruit_dht

# DHT22 data pins connected to BCM GPIO 4, 17, 18, 22, 23, 27
DATA_PINS = [board.D4, board.D17, board.D18, board.D22, board.D23, board.D27]

# Global list to track initialized sensors for cleanup
_sensors = []

def cleanup(signum=None, frame=None):
    """Release all DHT22 sensors on exit or signal."""
    for sensor in _sensors:
        try:
            sensor.exit()
        except Exception:
            pass
    _sensors.clear()
    if signum is not None:
        sys.exit(0)

def main():
    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    # Initialize DHT22 sensors on each data pin
    for pin in DATA_PINS:
        try:
            sensor = adafruit_dht.DHT22(pin, use_pulseio=False)
            _sensors.append(sensor)
        except Exception as e:
            print(f"Failed to initialize DHT22 on {pin}: {e}", file=sys.stderr)
            cleanup()
            sys.exit(1)

    # Run 3 measurement cycles
    for cycle in range(3):
        print(f"--- Cycle {cycle + 1}/3 ---")
        for idx, sensor in enumerate(_sensors):
            pin_label = DATA_PINS[idx].name if hasattr(DATA_PINS[idx], 'name') else str(DATA_PINS[idx])
            try:
                temperature = sensor.temperature
                humidity = sensor.humidity
                if temperature is not None and humidity is not None:
                    print(f"  {pin_label}: {temperature:.1f} C, {humidity:.1f} %")
                else:
                    print(f"  {pin_label}: No data (checksum error or timeout)")
            except RuntimeError as e:
                # DHT22 often throws transient read errors; report and continue
                print(f"  {pin_label}: Read error: {e}")
            except Exception as e:
                print(f"  {pin_label}: Unexpected error: {e}", file=sys.stderr)
        if cycle < 2:
            time.sleep(5)

    cleanup()

