import signal
import sys
import time
import board
import adafruit_dht

DHT_PIN = board.D4
READ_INTERVAL = 60
NUM_READINGS = 10

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_dht22(sensor):
    try:
        temperature = sensor.temperature
        humidity = sensor.humidity
    except RuntimeError as e:
        print(f"Error reading DHT22: {e}", file=sys.stderr)
        return None, None
    except Exception as e:
        print(f"Unexpected error reading DHT22: {e}", file=sys.stderr)
        return None, None

    if temperature is None or humidity is None:
        print("Error reading DHT22: sensor returned None", file=sys.stderr)
        return None, None

    if not (-40.0 <= temperature <= 80.0):
        print(f"Error reading DHT22: temperature out of range: {temperature}", file=sys.stderr)
        return None, None
    if not (0.0 <= humidity <= 100.0):
        print(f"Error reading DHT22: humidity out of range: {humidity}", file=sys.stderr)
        return None, None

    return temperature, humidity

def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        sensor = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
    except Exception as e:
        print(f"Failed to initialize DHT22 on GPIO 4: {e}", file=sys.stderr)
        sys.exit(1)

    readings_taken = 0
    try:
        while _running and readings_taken < NUM_READINGS:
            temperature, humidity = read_dht22(sensor)

            if temperature is not None and humidity is not None:
                print(f"Temperature: {temperature:.1f} C, Humidity: {humidity:.1f} %")
                readings_taken += 1
            else:
                print("Failed to get valid reading from DHT22.", file=sys.stderr)

            if readings_taken < NUM_READINGS and _running:
                time.sleep(READ_INTERVAL)
    finally:
        try:
            sensor.exit()
        except Exception:
            pass

if __name__ == "__main__":
    main()

import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 115200
READ_TIMEOUT = 1.0
LOOP_INTERVAL = 0.5

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def _validate_reading(value):
    if not isinstance(value, (int, float)):
        return False
    if value < -20.0 or value > 125.0:
        return False
    return True

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            timeout=READ_TIMEOUT,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE
        )
    except serial.SerialException as exc:
        print(f"Error: cannot open serial port {SERIAL_PORT}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                raw = ser.readline()
            except serial.SerialException as exc:
                print(f"Error: serial read failed: {exc}", file=sys.stderr)
                break

            if not raw:
                print("Error: no data received (device may be absent or unresponsive)")
                break

            try:
                text = raw.decode('ascii', errors='replace').strip()
            except Exception as exc:
                print(f"Error: decode failed: {exc}", file=sys.stderr)
                continue

            if not text:
                continue

            try:
                value = float(text)
            except ValueError:
                print(f"Error: invalid data format: {text!r}")
                continue

            if not _validate_reading(value):
                print(f"Error: reading out of range: {value}")
                continue

            print(f"Temperature: {value:.2f} C")

            time.sleep(LOOP_INTERVAL)
    finally:
        try:
            ser.close()
        except Exception:
            pass

if __name__ == '__main__':
    main()

