import signal
import sys
import time
import board
import adafruit_dht

DHT_PIN = board.D22
READ_INTERVAL = 3.0
MAX_CYCLES = 2
TIMEOUT = 5.0

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_dht22(sensor):
    deadline = time.monotonic() + TIMEOUT
    while time.monotonic() < deadline:
        try:
            temp = sensor.temperature
            hum = sensor.humidity
        except RuntimeError:
            time.sleep(0.5)
            continue
        if temp is None or hum is None:
            time.sleep(0.5)
            continue
        if not (-40.0 <= temp <= 80.0) or not (0.0 <= hum <= 100.0):
            time.sleep(0.5)
            continue
        return temp, hum
    return None, None

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        sensor = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
    except Exception as e:
        print(f"Failed to initialize DHT22 on GPIO 22: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        for cycle in range(1, MAX_CYCLES + 1):
            if not _running:
                break
            temp, hum = read_dht22(sensor)
            if temp is None or hum is None:
                print(f"Cycle {cycle}: DHT22 read failed (timeout or invalid data)")
            else:
                print(f"Cycle {cycle}: Temperature = {temp:.1f} C, Humidity = {hum:.1f} %")
            if cycle < MAX_CYCLES and _running:
                time.sleep(READ_INTERVAL)
    finally:
        try:
            sensor.exit()
        except Exception:
            pass

if __name__ == "__main__":
    main()

