import signal
import sys
import time
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

PINS = [0, 17]
DELAY = 0.5

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def validate_reading(value):
    if not isinstance(value, bool):
        raise ValueError(f"Invalid reading: {value!r}")
    return value

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    devices = []
    try:
        for pin in PINS:
            dev = OutputDevice(pin)
            devices.append(dev)
            print(f"Configured GPIO {pin} as output (initial state: off)")

        while _running:
            for dev in devices:
                try:
                    reading = validate_reading(True)
                    dev.on()
                    print(f"GPIO {dev.pin.number} set to HIGH")
                except ValueError as e:
                    print(f"Error: {e}", file=sys.stderr)
                except GPIOZeroError as e:
                    print(f"GPIO error on pin {dev.pin.number}: {e}", file=sys.stderr)

                if not _running:
                    break

                try:
                    reading = validate_reading(False)
                    dev.off()
                    print(f"GPIO {dev.pin.number} set to LOW")
                except ValueError as e:
                    print(f"Error: {e}", file=sys.stderr)
                except GPIOZeroError as e:
                    print(f"GPIO error on pin {dev.pin.number}: {e}", file=sys.stderr)

                if not _running:
                    break

                time.sleep(DELAY)

    except GPIOZeroError as e:
        print(f"GPIO initialization error: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        for dev in devices:
            try:
                dev.close()
            except Exception:
                pass
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

