import signal
import sys
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

PINS = [5, 6, 12]
CYCLES = 3

devices = []

def cleanup(signum=None, frame=None):
    for dev in devices:
        try:
            dev.close()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)

def apply_state(state):
    if not isinstance(state, (list, tuple)) or len(state) != len(PINS):
        raise ValueError(f"Invalid state length: expected {len(PINS)}, got {len(state) if isinstance(state, (list, tuple)) else type(state)}")
    for dev, val in zip(devices, state):
        if val not in (0, 1):
            raise ValueError(f"Invalid state value {val} for pin {dev.pin.number}")
        dev.value = val
    print(f"State applied: {state}")

def main():
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)
    try:
        for pin in PINS:
            dev = OutputDevice(pin)
            devices.append(dev)
        for i in range(CYCLES):
            apply_state([1, 0, 1])
    except GPIOZeroError as e:
        print(f"GPIO error: {e}", file=sys.stderr)
    except ValueError as e:
        print(f"Value error: {e}", file=sys.stderr)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        cleanup()

if __name__ == "__main__":
