import signal
import sys
import time

from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

PWM_PIN = 4
CYCLES = 3
INTERVAL = 5.0
DUTY_CYCLE = 0.5

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        pwm = PWMOutputDevice(PWM_PIN, frequency=100, initial_value=0)
    except GPIOZeroError as exc:
        print(f"Failed to initialize PWM on GPIO {PWM_PIN}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        for i in range(CYCLES):
            if not _running:
                break
            try:
                pwm.value = DUTY_CYCLE
                print(f"Cycle {i + 1}/{CYCLES}: PWM set to {DUTY_CYCLE * 100:.0f}%")
            except DeviceClosed:
                print("Device closed before cycle.", file=sys.stderr)
                break
            except GPIOZeroError as exc:
                print(f"Error setting PWM value: {exc}", file=sys.stderr)
                break

            elapsed = 0.0
            while _running and elapsed < INTERVAL:
                time.sleep(0.1)
                elapsed += 0.1

            if _running:
                try:
                    pwm.value = 0
                    print(f"Cycle {i + 1}/{CYCLES}: PWM set to 0%")
                except (DeviceClosed, GPIOZeroError) as exc:
                    print(f"Error resetting PWM: {exc}", file=sys.stderr)
                    break

        if _running:
            print("PWM control sequence completed.")
        else:
            print("Sequence interrupted by signal.")
    finally:
        try:
            pwm.value = 0
        except Exception:
            pass
        pwm.close()
        print("GPIO cleanup completed.")

if __name__ == "__main__":
