import time
from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIODeviceError, GPIOPinInUse

PWM_PIN = 14
INTERVAL = 5.0
MAX_RETRIES = 3
RETRY_DELAY = 1.0

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_pwm_value(device):
    """Read the current PWM duty cycle (0.0–1.0). Returns None on failure."""
    try:
        return device.value
    except Exception as exc:
        print(f"[WARN] Failed to read PWM value: {exc}", file=sys.stderr)
        return None

def apply_pwm(device, value):
    """Apply a validated PWM value (0.0–1.0). Returns True on success."""
    if not 0.0 <= value <= 1.0:
        print(f"[ERROR] Invalid PWM value {value}; must be 0.0–1.0", file=sys.stderr)
        return False
    try:
        device.value = value
        print(f"PWM value set to: {value:.4f}")
        return True
    except Exception as exc:
        print(f"[ERROR] Failed to set PWM value: {exc}", file=sys.stderr)
        return False

def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    device = None
    try:
        device = PWMOutputDevice(PWM_PIN)
        print(f"PWM output initialized on GPIO {PWM_PIN} (BCM).")

        while _running:
            pwm_value = read_pwm_value(device)
            if pwm_value is None:
                print("[ERROR] Could not read PWM value; skipping cycle.", file=sys.stderr)
            else:
                apply_pwm(device, pwm_value)

            elapsed = 0.0
            while _running and elapsed < INTERVAL:
                time.sleep(0.1)
                elapsed += 0.1

    except GPIOPinInUse:
        print(f"[ERROR] GPIO {PWM_PIN} is already in use by another process.", file=sys.stderr)
        sys.exit(1)
    except GPIODeviceError as exc:
        print(f"[ERROR] GPIO device error on pin {PWM_PIN}: {exc}", file=sys.stderr)
        sys.exit(1)
    except Exception as exc:
        print(f"[ERROR] Unexpected error: {exc}", file=sys.stderr)
        sys.exit(1)
    finally:
        if device is not None:
            try:
                device.close()
                print("PWM output device closed.")
            except Exception as exc:
                print(f"[WARN] Error closing device: {exc}", file=sys.stderr)
        print("Exiting program.")

if __name__ == "__main__":
    main()

import signal
import sys
import time
from smbus2 import SMBus, i2c_msg

I2C_BUS = 1
I2C_ADDR = 0x40
READ_INTERVAL = 2.0

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def _read_register(bus, reg):
    write_msg = i2c_msg.write(I2C_ADDR, [reg])
    read_msg = i2c_msg.read(I2C_ADDR, 2)
    bus.i2c_rdwr(write_msg, read_msg)
    raw = bytes(read_msg)
    if len(raw) < 2:
        raise IOError(f"Short read at register 0x{reg:02X}")
    return (raw[0] << 8) | raw[1]

def _read_ina219(bus):
    bus_addr = _read_register(bus, 0x00)
    if bus_addr != I2C_ADDR:
        raise IOError(f"INA219 not found at 0x{bus_addr:04X}, expected 0x{I2C_ADDR:04X}")
    voltage = _read_register(bus, 0x01)
    current = _read_register(bus, 0x02)
    power = _read_register(bus, 0x03)
    if voltage > 32767:
        raise ValueError(f"Voltage overflow: 0x{voltage:04X}")
    if current > 32767:
        raise ValueError(f"Current overflow: 0x{current:04X}")
    if power > 32767:
        raise ValueError(f"Power overflow: 0x{power:04X}")
    return voltage, current, power

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)
    try:
        bus = SMBus(I2C_BUS)
    except OSError as e:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)
    try:
        while _running:
            try:
                voltage, current, power = _read_ina219(bus)
                print(f"Voltage: {voltage}, Current: {current}, Power: {power}")
            except (IOError, ValueError) as e:
                print(f"Error reading INA219: {e}", file=sys.stderr)
            time.sleep(READ_INTERVAL)
    finally:
        bus.close()

if __name__ == "__main__":
    main()

