import signal
import sys
import time

import board
import busio
import adafruit_ads1x15.ads1115 as ADS
from adafruit_ads1x15.analog_in import AnalogIn

# --- Configuration -----------------------------------------------------------
I2C_ADDRESS = 0x48          # ADS1115 default I2C address (ADDR -> GND)
SAMPLE_INTERVAL = 0.1       # seconds between readings
# -----------------------------------------------------------------------------

_running = True


def _handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


def main() -> int:
    global _running

    # Install signal handlers for clean exit
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    # Initialize I2C bus (board.SCL / board.SDA uses the Pi's hardware I2C pins)
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        print(f"Error: failed to initialize I2C bus: {exc}", file=sys.stderr)
        return 1

    # Initialize the ADS1115 at the specified address
    try:
        ads = ADS.ADS1115(i2c, address=I2C_ADDRESS)
    except ValueError:
        print(f"Error: no ADS1115 found at I2C address 0x{I2C_ADDRESS:02X}.", file=sys.stderr)
        return 1
    except Exception as exc:
        print(f"Error: ADS1115 initialization failed: {exc}", file=sys.stderr)
        return 1

    # Create a single-ended analog input on channel 0
    try:
        chan = AnalogIn(ads, ADS.P0)
    except Exception as exc:
        print(f"Error: failed to configure analog input: {exc}", file=sys.stderr)
        return 1

    print("Starting ADS1115 sampling. Press Ctrl+C to stop.")

    try:
        while _running:
            try:
                voltage = chan.voltage
                # Basic sanity check: ADS1115 is 16-bit, so voltage should be in [0, 3.3]
                if not (0.0 <= voltage <= 3.3):
                    print(f"Warning: out-of-range reading {voltage:.4f} V", file=sys.stderr)
                else:
                    print(f"Voltage: {voltage:.4f} V")
            except OSError as exc:
                # I2C bus error (e.g., device disconnected mid-stream)
                print(f"Warning: I2C read error: {exc}", file=sys.stderr)
            except Exception as exc:
                print(f"Warning: unexpected read error: {exc}", file=sys.stderr)

            time.sleep(SAMPLE_INTERVAL)
    finally:
        # Release hardware resources on every exit path
        try:
            chan.deinit()
        except Exception:
            pass
        try:
            ads.deinit()
        except Exception:
            pass
        try:
            i2c.deinit()
        except Exception:
            pass
        print("Resources released. Exiting.")

    return 0


if __name__ == "__main__":
    sys.exit(main())

import signal
import sys
import time
from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIODeviceError, GPIOPinInUse

PWM_PINS = [5, 6, 13, 17, 18, 22, 23, 24, 27]
PWM_FREQUENCY = 1000  # Hz
running = True


def handle_signal(signum, frame):
    global running
    running = False


def validate_pwm_value(value):
    if not isinstance(value, (int, float)):
        raise ValueError("PWM value must be numeric")
    if not 0.0 <= value <= 100.0:
        raise ValueError("PWM value must be between 0 and 100")
    return float(value)


def main():
    global running
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    devices = []
    try:
        for pin in PWM_PINS:
            try:
                dev = PWMOutputDevice(pin, frequency=PWM_FREQUENCY, initial_value=0.0)
                devices.append(dev)
                print(f"PWM initialized on GPIO {pin} at {PWM_FREQUENCY} Hz")
            except (GPIODeviceError, GPIOPinInUse) as e:
                print(f"Error initializing PWM on GPIO {pin}: {e}", file=sys.stderr)
                raise
            except Exception as e:
                print(f"Unexpected error on GPIO {pin}: {e}", file=sys.stderr)
                raise

        while running:
            for i, dev in enumerate(devices):
                try:
                    value = 50.0
                    validated = validate_pwm_value(value)
                    dev.value = validated / 100.0
                    print(f"GPIO {PWM_PINS[i]} set to {validated:.1f}%")
                except ValueError as e:
                    print(f"Invalid PWM value for GPIO {PWM_PINS[i]}: {e}", file=sys.stderr)
                except Exception as e:
                    print(f"Error setting PWM on GPIO {PWM_PINS[i]}: {e}", file=sys.stderr)
            time.sleep(1)

    except Exception as e:
        print(f"Fatal error: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        for dev in devices:
            try:
                dev.value = 0.0
                dev.close()
            except Exception:
                pass
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

