from gpiozero import OutputDevice
from gpiozero.exc import GPIODeviceError, GPIOPinInUse

PIN_HIGH = 2
PIN_LOW = 17
DELAY = 0.1

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        dev_high = OutputDevice(PIN_HIGH)
        dev_low = OutputDevice(PIN_LOW)
    except (GPIODeviceError, GPIOPinInUse) as exc:
        print(f"Error: failed to initialize GPIO pins {PIN_HIGH}/{PIN_LOW}: {exc}", file=sys.stderr)
        sys.exit(1)
    except Exception as exc:
        print(f"Error: unexpected failure during GPIO init: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                dev_high.on()
                dev_low.off()
                print(f"GPIO{PIN_HIGH}=HIGH  GPIO{PIN_LOW}=LOW")
            except Exception as exc:
                print(f"Error: failed to write HIGH/LOW: {exc}", file=sys.stderr)
                break

            time.sleep(DELAY)

            if not _running:
                break

            try:
                dev_high.off()
                dev_low.on()
                print(f"GPIO{PIN_HIGH}=LOW   GPIO{PIN_LOW}=HIGH")
            except Exception as exc:
                print(f"Error: failed to write LOW/HIGH: {exc}", file=sys.stderr)
                break

            time.sleep(DELAY)
