        print(f"I/O error: {e}", file=sys.stderr)
        return None

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    ser = None
    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            timeout=READ_TIMEOUT
        )
        print(f"Opened {SERIAL_PORT} @ {BAUD_RATE} baud")

        readings_taken = 0
        while _running and readings_taken < NUM_READINGS:
            data = read_sensor_data(ser)
            if data is not None:
                print(f"Sensor reading: {data}")
            else:
                print("No data received (device may be absent or unresponsive).", file=sys.stderr)
            readings_taken += 1
            if readings_taken < NUM_READINGS and _running:
                time.sleep(INTERVAL_SECONDS)

    except serial.SerialException as e:
        print(f"Failed to open serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)
    except OSError as e:
        print(f"OS error opening {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

