import signal
import sys
import time

import board
import adafruit_dht

DHT_PIN = board.D4
READ_INTERVAL = 5
NUM_READINGS = 3

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_dht22(sensor):
    try:
        temperature = sensor.temperature
        humidity = sensor.humidity
    except RuntimeError as e:
        print(f"Error reading DHT22: {e}", file=sys.stderr)
        return None, None
    except Exception as e:
        print(f"Unexpected error reading DHT22: {e}", file=sys.stderr)
        return None, None

    if temperature is None or humidity is None:
        print("Error reading DHT22: Invalid data received.", file=sys.stderr)
        return None, None

    if not (-40 <= temperature <= 80):
        print(f"Error reading DHT22: Temperature out of range: {temperature}", file=sys.stderr)
        return None, None
    if not (0 <= humidity <= 100):
        print(f"Error reading DHT22: Humidity out of range: {humidity}", file=sys.stderr)
        return None, None

    return temperature, humidity

def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        sensor = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
    except Exception as e:
        print(f"Failed to initialize DHT22 on GPIO 4: {e}", file=sys.stderr)
        sys.exit(1)

    readings_taken = 0
    try:
        while _running and readings_taken < NUM_READINGS:
            temperature, humidity = read_dht22(sensor)

            if temperature is not None and humidity is not None:
                print(f"Temperature: {temperature:.1f} C, Humidity: {humidity:.1f} %")
                readings_taken += 1
            else:
                print("Skipping this reading due to error.")

            if readings_taken < NUM_READINGS and _running:
                time.sleep(READ_INTERVAL)
    finally:
        try:
            sensor.exit()
        except Exception:
            pass

if __name__ == "__main__":
    main()

import signal
import sys
import time
import board
import adafruit_dht

DHT_PIN = board.D4
CYCLES = 3
DELAY_S = 2.0

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    sensor = None
    try:
        sensor = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
        print(f"DHT22 initialized on GPIO 4 (BCM). Starting {CYCLES} cycles.")

        for cycle in range(1, CYCLES + 1):
            if not _running:
                print("Shutdown requested; exiting early.")
                break

            try:
                temperature = sensor.temperature
                humidity = sensor.humidity
                if temperature is None or humidity is None:
                    print(f"Cycle {cycle}: sensor read failed (None).")
                else:
                    print(f"Cycle {cycle}: {temperature:.1f} C, {humidity:.1f} %")
            except RuntimeError as e:
                print(f"Cycle {cycle}: read error: {e}")
            except Exception as e:
                print(f"Cycle {cycle}: unexpected error: {e}")

            if cycle < CYCLES and _running:
                time.sleep(DELAY_S)

        print("DHT22 monitoring complete.")

    except Exception as e:
        print(f"Initialization error: {e}", file=sys.stderr)
    finally:
        if sensor is not None:
            try:
                sensor.exit()
            except Exception:
                pass
        print("Resources released.")

if __name__ == "__main__":
    main()
